<?php
require __DIR__.'/includes/bootstrap.php';
if(!isset($_SESSION['cart'])||!is_array($_SESSION['cart']))$_SESSION['cart']=[];
if($_SERVER['REQUEST_METHOD']==='POST'){
 verify_csrf();$action=$_POST['action']??'';$id=(int)($_POST['product_id']??0);
 if($action==='add'&&$id>0){$q=db()->prepare('SELECT id,stock FROM products WHERE id=? AND active=1');$q->execute([$id]);$p=$q->fetch();if($p){$qty=max(1,min(99,(int)($_POST['quantity']??1)));$_SESSION['cart'][$id]=min(99,(int)($_SESSION['cart'][$id]??0)+$qty);flash('Produto adicionado ao carrinho.');}else flash('Produto indisponível.','error');}
 if($action==='update'){foreach(($_POST['quantities']??[]) as $pid=>$qty){$pid=(int)$pid;$qty=(int)$qty;if($qty<=0)unset($_SESSION['cart'][$pid]);else $_SESSION['cart'][$pid]=min(99,$qty);}}
 if($action==='remove'){unset($_SESSION['cart'][$id]);}
 if($action==='checkout'){header('Location: pedido.php?origem=carrinho');exit;}
 header('Location: carrinho.php');exit;
}
$items=[];$total=0;if($_SESSION['cart']){$ids=array_map('intval',array_keys($_SESSION['cart']));$in=implode(',',array_fill(0,count($ids),'?'));$q=db()->prepare("SELECT * FROM products WHERE active=1 AND id IN ($in)");$q->execute($ids);foreach($q->fetchAll() as $p){$qty=(int)$_SESSION['cart'][$p['id']];$unit=(float)($p['promotional_price']??$p['price']);$line=$unit*$qty;$p['cart_qty']=$qty;$p['cart_unit']=$unit;$p['cart_line']=$line;$items[]=$p;$total+=$line;}}
?><!doctype html><html lang="pt-br"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Carrinho | F&J Artes Presentes</title><link rel="stylesheet" href="assets/style.css"></head><body class="install-page"><main class="install-card cart-card"><a class="text-link" href="index.php">← Continuar comprando</a><div class="brand-mark">F&J</div><h1>Meu carrinho</h1><?php show_flash();?><?php if(!$items):?><div class="empty">Seu carrinho está vazio.</div><a class="btn primary full" href="index.php#produtos">Ver produtos</a><?php else:?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="update"><?php foreach($items as $it):?><div class="cart-row"><?php if($it['image_path']):?><img src="<?=e($it['image_path'])?>" alt=""><?php endif;?><div class="cart-info"><strong><?=e($it['name'])?></strong><small>R$ <?=number_format($it['cart_unit'],2,',','.')?> cada</small><label>Quantidade<input type="number" name="quantities[<?=$it['id']?>]" min="0" max="99" value="<?=$it['cart_qty']?>"></label></div><b>R$ <?=number_format($it['cart_line'],2,',','.')?></b><button class="btn danger" form="remove<?=$it['id']?>">Remover</button></div><?php endforeach;?><button class="btn outline">Atualizar quantidades</button></form><div class="cart-total"><span>Total estimado</span><strong>R$ <?=number_format($total,2,',','.')?></strong></div><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="checkout"><button class="btn primary full">Finalizar pedido pelo WhatsApp</button></form><?php foreach($items as $it):?><form hidden id="remove<?=$it['id']?>" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="remove"><input type="hidden" name="product_id" value="<?=$it['id']?>"></form><?php endforeach;?><?php endif;?></main></body></html>
